import json
from pathlib import Path
p = Path('/root/syncpack_analysis.json')
data = json.load(open(p))
expected_top = ['assumptions', 'medications', 'totals', 'recommendation']
expected_assumptions = ['patients_per_medication', 'fills_per_year_28_day', 'fills_per_year_56_day', 'capsules_per_fill_28_day', 'capsules_per_fill_56_day', 'switch_threshold_usd']
expected_med = ['medication', 'price_per_1000_capsules_usd', 'blister_card_count', 'card_cost_usd', 'reimbursement_per_cycle_180_patients_usd', 'annual_drug_cost_28_day_usd', 'annual_drug_cost_56_day_usd', 'annual_packaging_cost_28_day_usd', 'annual_packaging_cost_56_day_usd', 'annual_reimbursement_28_day_usd', 'annual_reimbursement_56_day_usd', 'annual_margin_28_day_usd', 'annual_margin_56_day_usd', 'annual_margin_difference_56_minus_28_usd']
errors = []
if list(data.keys()) != expected_top:
    errors.append(f'top keys {list(data.keys())}')
if list(data['assumptions'].keys()) != expected_assumptions:
    errors.append(f'assumption keys {list(data["assumptions"].keys())}')
if 'dosing' in data['assumptions']:
    errors.append('dosing present')
if data['assumptions'].get('capsules_per_fill_28_day') != 56:
    errors.append('capsules_per_fill_28_day wrong')
if data['assumptions'].get('fills_per_year_28_day') != 12:
    errors.append('fills_per_year_28_day wrong')
if not isinstance(data['recommendation'], dict) or list(data['recommendation'].keys()) != ['decision', 'justification']:
    errors.append('recommendation schema wrong')
med_names = [m['medication'] for m in data['medications']]
if med_names != sorted(med_names):
    errors.append('medications not sorted')
for i, m in enumerate(data['medications']):
    if list(m.keys()) != expected_med:
        errors.append(f'medication {i} keys wrong: {list(m.keys())}')
    for k, v in m.items():
        if k.endswith('_usd') and isinstance(v, float) and round(v, 2) != v:
            errors.append(f'{m.get("medication")} {k} not rounded: {v}')
for k, v in data['totals'].items():
    if k.endswith('_usd') and isinstance(v, float) and round(v, 2) != v:
        errors.append(f'total {k} not rounded: {v}')
summary_lines = [line for line in Path('/root/syncpack_summary.md').read_text().splitlines() if line.strip()]
if not (4 <= len(summary_lines) <= 8):
    errors.append(f'summary line count {len(summary_lines)}')
for needle in ['Total 28-day margin in USD', 'Total 56-day margin in USD', 'Absolute difference in USD', data['recommendation']['decision']]:
    if not any(needle in line for line in summary_lines):
        errors.append(f'summary missing {needle}')
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION OK')
print('medications:', ', '.join(med_names))
print('decision:', data['recommendation']['decision'])
print('totals:', data['totals'])
